import os, sys, glob, json, io
import numpy as np
import pandas as pd
import torch
import torch.nn as nn
import torch.nn.functional as F
from PIL import Image
from torch.utils.data import DataLoader, Dataset

working_dir = os.path.join(os.getcwd(), "working")
os.makedirs(working_dir, exist_ok=True)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print(f"Using device: {device}")

DATA_DIR = "/data/zhenqian/data"
MODEL_DIR = "/data/zhenqian/models"

experiment_data = {
    "THINGS": {
        "metrics": {"train": [], "val": []},
        "losses": {"train": [], "val": []},
        "predictions": [],
        "ground_truth": [],
        "baseline_ooo_acc": None,
        "teacher_ooo_acc": None,
        "aligned_ooo_acc": None,
    }
}

# ---------- Locate triplet CSV ----------
trip_dir = os.path.join(DATA_DIR, "things_ooo_triplets")
trip_candidates = []
for root, dirs, files in os.walk(trip_dir):
    if "__MACOSX" in root:
        continue
    for f in files:
        if f.startswith(".") or f.startswith("._"):
            continue
        if f.endswith(".csv") or f.endswith(".tsv") or f.endswith(".txt"):
            trip_candidates.append(os.path.join(root, f))
print("Triplet candidates:", trip_candidates[:10])

triplet_file = None
for c in trip_candidates:
    if "triplet" in c.lower() and "final" in c.lower():
        triplet_file = c
        break
if triplet_file is None and trip_candidates:
    # pick largest
    triplet_file = max(trip_candidates, key=lambda p: os.path.getsize(p))
print("Using triplet file:", triplet_file)


# Parse triplets
def load_triplets(path):
    for sep in ["\t", ",", " "]:
        try:
            df = pd.read_csv(path, sep=sep, engine="python")
            if df.shape[1] >= 3:
                return df, sep
        except Exception:
            continue
    raise RuntimeError("Could not parse triplet file")


df, sep = load_triplets(triplet_file)
print("Triplet df shape:", df.shape, "sep=", repr(sep))
print("Columns:", list(df.columns))
print(df.head(3))

# Identify columns
cols = [c.lower() for c in df.columns]


def find_col(keys):
    for i, c in enumerate(cols):
        for k in keys:
            if k in c:
                return df.columns[i]
    return None


c_img1 = find_col(["image1", "img1"])
c_img2 = find_col(["image2", "img2"])
c_img3 = find_col(["image3", "img3"])
c_choice = find_col(["choice", "ooo", "odd"])

if c_img1 is None:
    # assume first 3 are triplet
    c_img1, c_img2, c_img3 = df.columns[0], df.columns[1], df.columns[2]
    if c_choice is None and df.shape[1] >= 4:
        c_choice = df.columns[3]

print(f"Using cols: {c_img1},{c_img2},{c_img3}, choice={c_choice}")


# Convert to numeric
def to_int(col):
    return pd.to_numeric(df[col], errors="coerce").to_numpy()


img1 = to_int(c_img1)
img2 = to_int(c_img2)
img3 = to_int(c_img3)
choice = to_int(c_choice) if c_choice else None

mask = ~(np.isnan(img1) | np.isnan(img2) | np.isnan(img3))
if choice is not None:
    mask &= ~np.isnan(choice)
img1, img2, img3 = (
    img1[mask].astype(np.int64),
    img2[mask].astype(np.int64),
    img3[mask].astype(np.int64),
)
if choice is not None:
    choice = choice[mask].astype(np.int64)

# Determine indexing: 0- or 1-indexed
min_id = min(img1.min(), img2.min(), img3.min())
max_id = max(img1.max(), img2.max(), img3.max())
print(f"ID range: [{min_id}, {max_id}]")
if min_id == 1:
    img1 -= 1
    img2 -= 1
    img3 -= 1
    if choice is not None and choice.min() >= 1 and choice.max() <= 3:
        # choice may be position 1/2/3
        pass

triplets = np.stack([img1, img2, img3], axis=1)
n_concepts_from_triplets = int(triplets.max()) + 1
print(
    f"n_concepts_from_triplets = {n_concepts_from_triplets}, n_triplets = {len(triplets)}"
)

# Determine OOO index (position 0/1/2) from choice
# The 'choice' column in THINGS typically stores the concept id of the odd-one-out
if choice is None:
    raise RuntimeError("No choice column found")

# Try: choice is concept id
c_adj = choice.copy()
if min_id == 1:
    c_adj = c_adj - 1

matches_as_id = ((c_adj == img1) | (c_adj == img2) | (c_adj == img3)).mean()
print(f"Fraction choice matches as concept id: {matches_as_id:.3f}")

if matches_as_id > 0.9:
    ooo_pos = np.where(c_adj == img1, 0, np.where(c_adj == img2, 1, 2))
else:
    # Try choice as position 1/2/3 or 0/1/2
    if choice.min() >= 1 and choice.max() <= 3:
        ooo_pos = choice - 1
    elif choice.min() >= 0 and choice.max() <= 2:
        ooo_pos = choice.copy()
    else:
        raise RuntimeError(
            f"Cannot interpret choice column: min={choice.min()}, max={choice.max()}"
        )

print(f"OOO position distribution: {np.bincount(ooo_pos, minlength=3)}")

# ---------- Locate concept images ----------
img_root = os.path.join(DATA_DIR, "things_ooo_root")
print(f"Scanning image root: {img_root}")

# Find all directories that contain image files
concept_dirs = {}
image_exts = {".jpg", ".jpeg", ".png", ".JPEG"}

# Look for reference_images typical folder
ref_candidates = []
for root, dirs, files in os.walk(img_root):
    if "__MACOSX" in root:
        continue
    dirs[:] = [
        d for d in dirs if not d.startswith(".") and not d.startswith("__MACOSX")
    ]
    # count images
    imgs = [
        f
        for f in files
        if os.path.splitext(f)[1].lower() in {".jpg", ".jpeg", ".png"}
        and not f.startswith(".")
    ]
    if len(imgs) >= 1 and len(imgs) <= 30:
        # this may be a concept dir
        ref_candidates.append((root, imgs))

print(f"Found {len(ref_candidates)} candidate concept dirs")

# Better: find parent dirs that contain many subdirs each with images
parent_counts = {}
for root, imgs in ref_candidates:
    parent = os.path.dirname(root)
    parent_counts[parent] = parent_counts.get(parent, 0) + 1

best_parent = (
    max(parent_counts.items(), key=lambda x: x[1]) if parent_counts else (None, 0)
)
print(f"Best concept-container: {best_parent}")

# Also check for single-image-per-concept layout
if best_parent[1] < 1000:
    # try flat layout: images named by concept
    for root, dirs, files in os.walk(img_root):
        if "__MACOSX" in root:
            continue
        imgs = [
            f
            for f in files
            if os.path.splitext(f)[1].lower() in {".jpg", ".jpeg", ".png"}
            and not f.startswith(".")
        ]
        if 1500 <= len(imgs) <= 3000:
            print(f"Flat layout candidate: {root} with {len(imgs)} images")

# Build concept -> image path mapping using best_parent
concept_image_paths = {}  # index -> path
if best_parent[0] is not None and best_parent[1] > 500:
    parent = best_parent[0]
    subdirs = sorted(
        [
            d
            for d in os.listdir(parent)
            if os.path.isdir(os.path.join(parent, d)) and not d.startswith(".")
        ]
    )
    print(f"Concept dirs in parent: {len(subdirs)}")
    # Load concept names mapping if available
    for i, sd in enumerate(subdirs):
        sd_path = os.path.join(parent, sd)
        imgs = sorted(
            [
                f
                for f in os.listdir(sd_path)
                if os.path.splitext(f)[1].lower() in {".jpg", ".jpeg", ".png"}
                and not f.startswith(".")
            ]
        )
        if imgs:
            concept_image_paths[i] = os.path.join(sd_path, imgs[0])

# Also look for concept names file to align ordering
name_files = []
for root, dirs, files in os.walk(DATA_DIR):
    if "__MACOSX" in root:
        continue
    for f in files:
        if f.startswith("."):
            continue
        if "concept" in f.lower() and (
            f.endswith(".txt") or f.endswith(".csv") or f.endswith(".tsv")
        ):
            name_files.append(os.path.join(root, f))
        if f.lower() in ["unique_id.txt", "things_concepts.tsv"]:
            name_files.append(os.path.join(root, f))
print("Concept name files:", name_files[:5])

# Try to load concept ordering
concept_names = None
for nf in name_files:
    try:
        if nf.endswith(".tsv") or nf.endswith(".csv"):
            for sep_try in ["\t", ","]:
                try:
                    ndf = pd.read_csv(nf, sep=sep_try)
                    if len(ndf) >= 1800:
                        concept_names = ndf
                        print(
                            f"Loaded concept names from {nf}: shape {ndf.shape}, cols {list(ndf.columns)}"
                        )
                        break
                except:
                    pass
        else:
            with open(nf) as f:
                lines = [l.strip() for l in f if l.strip()]
            if len(lines) >= 1800:
                concept_names = lines
                print(f"Loaded {len(lines)} names from {nf}")
        if concept_names is not None:
            break
    except Exception as e:
        continue

# If subdirs sorted alphabetically matches concept order, we may need to reorder
# For now, use alphabetical subdirs as concept index
print(f"concept_image_paths size: {len(concept_image_paths)}")

# Try to match ordering via concept_names
if (
    concept_names is not None
    and best_parent[0] is not None
    and len(concept_image_paths) > 0
):
    parent = best_parent[0]
    subdirs = sorted(
        [
            d
            for d in os.listdir(parent)
            if os.path.isdir(os.path.join(parent, d)) and not d.startswith(".")
        ]
    )
    # Get list of names from concept_names
    name_list = None
    if isinstance(concept_names, pd.DataFrame):
        # find column that looks like uniqueID
        for c in concept_names.columns:
            vals = concept_names[c].astype(str).tolist()
            common = set(vals) & set(subdirs)
            if len(common) > 1000:
                name_list = vals
                print(f"Using column {c} for concept ordering, {len(common)} matches")
                break
    else:
        name_list = concept_names
        common = set(name_list) & set(subdirs)
        print(f"Text file match: {len(common)}")
        if len(common) < 1000:
            name_list = None

    if name_list is not None:
        # rebuild concept_image_paths using name_list order
        new_paths = {}
        for i, nm in enumerate(name_list):
            sd_path = os.path.join(parent, nm)
            if os.path.isdir(sd_path):
                imgs = sorted(
                    [
                        f
                        for f in os.listdir(sd_path)
                        if os.path.splitext(f)[1].lower() in {".jpg", ".jpeg", ".png"}
                        and not f.startswith(".")
                    ]
                )
                if imgs:
                    new_paths[i] = os.path.join(sd_path, imgs[0])
        if len(new_paths) >= 1800:
            concept_image_paths = new_paths
            print(f"Reordered by concept names: {len(new_paths)}")

n_concepts = max(concept_image_paths.keys()) + 1 if concept_image_paths else 0
print(
    f"Final n_concepts with images: {len(concept_image_paths)}, max_idx: {n_concepts}"
)

# Filter triplets to those with all images available
avail = set(concept_image_paths.keys())
valid_mask = np.array(
    [a in avail and b in avail and c in avail for a, b, c in triplets]
)
print(f"Valid triplets: {valid_mask.sum()} / {len(triplets)}")
triplets_v = triplets[valid_mask]
ooo_pos_v = ooo_pos[valid_mask]

if len(triplets_v) < 100:
    raise RuntimeError(f"Too few valid triplets: {len(triplets_v)}")

# Subsample triplets for evaluation to save time
np.random.seed(0)
max_eval = 50000
if len(triplets_v) > max_eval:
    idx = np.random.choice(len(triplets_v), max_eval, replace=False)
    triplets_v = triplets_v[idx]
    ooo_pos_v = ooo_pos_v[idx]
print(f"Using {len(triplets_v)} triplets for evaluation")

# ---------- Load DINOv2 ViT-B ----------
from transformers import AutoModel, AutoImageProcessor

dino_dir = None
for cand in [
    os.path.join(MODEL_DIR, "dinov2-base"),
    os.path.join(MODEL_DIR, "dinov2_vitb14"),
    os.path.join(MODEL_DIR, "dinov2-vitb14"),
]:
    if os.path.isdir(cand):
        dino_dir = cand
        break
if dino_dir is None:
    # search
    for d in os.listdir(MODEL_DIR):
        if "dinov2" in d.lower() and (
            "base" in d.lower() or "vitb" in d.lower() or "b14" in d.lower()
        ):
            dino_dir = os.path.join(MODEL_DIR, d)
            break
    if dino_dir is None:
        for d in os.listdir(MODEL_DIR):
            if "dinov2" in d.lower():
                dino_dir = os.path.join(MODEL_DIR, d)
                break
print(f"DINOv2 dir: {dino_dir}")

processor = AutoImageProcessor.from_pretrained(dino_dir, local_files_only=True)
dino = AutoModel.from_pretrained(dino_dir, local_files_only=True).to(device).eval()
for p in dino.parameters():
    p.requires_grad = False


# ---------- Extract DINOv2 features for all concepts ----------
class ConceptDS(Dataset):
    def __init__(self, paths_dict, processor):
        self.items = sorted(paths_dict.items())  # list of (idx, path)
        self.processor = processor

    def __len__(self):
        return len(self.items)

    def __getitem__(self, i):
        idx, path = self.items[i]
        img = Image.open(path).convert("RGB")
        px = self.processor(images=img, return_tensors="pt")["pixel_values"][0]
        return idx, px


ds = ConceptDS(concept_image_paths, processor)
dl = DataLoader(ds, batch_size=32, num_workers=4, shuffle=False)

print("Extracting DINOv2 features...")
dino_feats = {}
with torch.no_grad():
    for idxs, pxs in dl:
        pxs = pxs.to(device)
        out = dino(pixel_values=pxs)
        feats = out.last_hidden_state[:, 0, :]  # CLS
        feats = feats.cpu().numpy()
        for j, i in enumerate(idxs.tolist()):
            dino_feats[i] = feats[j]

dino_dim = next(iter(dino_feats.values())).shape[0]
print(f"DINO feature dim: {dino_dim}, extracted: {len(dino_feats)}")

# Assemble feature matrix
max_idx = max(dino_feats.keys()) + 1
dino_mat = np.zeros((max_idx, dino_dim), dtype=np.float32)
have = np.zeros(max_idx, dtype=bool)
for i, f in dino_feats.items():
    dino_mat[i] = f
    have[i] = True
print(f"DINO matrix shape: {dino_mat.shape}, coverage: {have.sum()}/{max_idx}")

# Sanity: nontrivial variance
print(f"DINO feature std mean: {dino_mat[have].std(0).mean():.4f}")


# ---------- OOO evaluation function ----------
def ooo_accuracy(feat_mat, triplets, gt_pos):
    F_t = torch.from_numpy(feat_mat).to(device).float()
    F_n = F.normalize(F_t, dim=1)
    a = F_n[triplets[:, 0]]
    b = F_n[triplets[:, 1]]
    c = F_n[triplets[:, 2]]
    s_ab = (a * b).sum(-1)
    s_ac = (a * c).sum(-1)
    s_bc = (b * c).sum(-1)
    # avg sim of each item to others
    avg_a = (s_ab + s_ac) / 2
    avg_b = (s_ab + s_bc) / 2
    avg_c = (s_ac + s_bc) / 2
    sims = torch.stack([avg_a, avg_b, avg_c], dim=1)
    pred_ooo = sims.argmin(dim=1).cpu().numpy()  # lowest avg sim = odd-one-out
    acc = (pred_ooo == gt_pos).mean()
    return acc, pred_ooo


# Validate OOO with synthetic sanity check
print("\n--- Sanity check: synthetic ---")
np.random.seed(1)
syn = np.random.randn(10, 32).astype(np.float32)
syn[3] += 100  # concept 3 far from others
syn_trip = np.array([[0, 1, 3], [1, 2, 3], [0, 3, 2]])
syn_gt = np.array([2, 2, 1])  # position of concept 3
acc_syn, _ = ooo_accuracy(syn, syn_trip, syn_gt)
print(f"Synthetic OOO acc (should be 1.0): {acc_syn:.4f}")
assert acc_syn > 0.99, "OOO function broken"

# Baseline DINOv2 OOO
baseline_acc, baseline_pred = ooo_accuracy(dino_mat, triplets_v, ooo_pos_v)
print(f"\n=== DINOv2 baseline OOO accuracy: {baseline_acc:.4f} ===")
experiment_data["THINGS"]["baseline_ooo_acc"] = float(baseline_acc)

# ---------- Load teacher features (SigLIP cache) ----------
cache_dir = os.path.join(DATA_DIR, "things_ooo_cache")
teacher_mat = None
if os.path.isdir(cache_dir):
    try:
        import h5py

        h5s = glob.glob(os.path.join(cache_dir, "*.h5"))
        print("H5 files:", h5s)
        for h5f in h5s:
            with h5py.File(h5f, "r") as f:
                keys = list(f.keys())
                print(f"{h5f} keys: {keys}")
                for k in keys:
                    d = f[k]
                    if hasattr(d, "shape"):
                        print(f"  {k}: shape={d.shape}, dtype={d.dtype}")
                # Try to find feature matrix and labels
                feat_key = None
                label_key = None
                for k in keys:
                    if (
                        hasattr(f[k], "shape")
                        and len(f[k].shape) == 2
                        and f[k].shape[1] >= 256
                    ):
                        feat_key = k
                    if (
                        "label" in k.lower()
                        or "concept" in k.lower()
                        or "id" in k.lower()
                    ):
                        label_key = k
                if feat_key:
                    feats = f[feat_key][:]
                    print(f"Teacher features: {feats.shape}")
                    if (
                        feats.shape[0] == n_concepts_from_triplets
                        or feats.shape[0] == max_idx
                    ):
                        teacher_mat = feats.astype(np.float32)
                    elif label_key:
                        labels = f[label_key][:]
                        print(
                            f"Labels shape: {labels.shape}, range: [{labels.min()}, {labels.max()}]"
                        )
                        # pool per concept
                        lbl_off = 1 if labels.min() == 1 else 0
                        nc = int(labels.max()) - lbl_off + 1
                        pooled = np.zeros((nc, feats.shape[1]), dtype=np.float32)
                        counts = np.zeros(nc, dtype=np.int64)
                        for i in range(len(labels)):
                            l = int(labels[i]) - lbl_off
                            pooled[l] += feats[i]
                            counts[l] += 1
                        counts_safe = np.maximum(counts, 1)
                        pooled = pooled / counts_safe[:, None]
                        teacher_mat = pooled
                        print(
                            f"Pooled teacher: {pooled.shape}, valid concepts: {(counts>0).sum()}"
                        )
                    else:
                        # assume rows correspond to concepts if right count nearby
                        if feats.shape[0] >= max_idx:
                            teacher_mat = feats[:max_idx].astype(np.float32)
                        break
            if teacher_mat is not None:
                break
    except Exception as e:
        print(f"Teacher cache load error: {e}")

teacher_acc = None
if teacher_mat is not None and teacher_mat.shape[0] >= max_idx:
    tm = teacher_mat[:max_idx]
    if tm.std(0).mean() > 1e-5:
        teacher_acc, _ = ooo_accuracy(tm, triplets_v, ooo_pos_v)
        print(f"=== Teacher OOO accuracy: {teacher_acc:.4f} ===")
        experiment_data["THINGS"]["teacher_ooo_acc"] = float(teacher_acc)
    else:
        print("Teacher features degenerate, skipping teacher")
        teacher_mat = None
else:
    print(f"Teacher features not usable (shape mismatch or missing)")
    teacher_mat = None

# ---------- Distillation: train projection head on DINOv2 to match teacher ----------
if (
    teacher_mat is not None
    and teacher_acc is not None
    and teacher_acc > 0.40
    and baseline_acc > 0.35
):
    print("\n=== Training projection head for alignment ===")
    tm = teacher_mat[:max_idx]
    # Valid indices where both dino and teacher exist
    valid_idx = np.where(have)[0]
    # Also require teacher feat nontrivial
    t_valid = tm[valid_idx].std(1) > 1e-5
    valid_idx = valid_idx[t_valid]
    print(f"Valid indices for training: {len(valid_idx)}")

    # Split into train/val by concepts
    np.random.seed(42)
    perm = np.random.permutation(len(valid_idx))
    n_val = int(len(valid_idx) * 0.1)
    val_idx = valid_idx[perm[:n_val]]
    train_idx = valid_idx[perm[n_val:]]

    X_train = torch.from_numpy(dino_mat[train_idx]).float().to(device)
    Y_train = torch.from_numpy(tm[train_idx]).float().to(device)
    X_val = torch.from_numpy(dino_mat[val_idx]).float().to(device)
    Y_val = torch.from_numpy(tm[val_idx]).float().to(device)

    teacher_dim = tm.shape[1]
    proj = nn.Sequential(
        nn.Linear(dino_dim, 1024),
        nn.GELU(),
        nn.Linear(1024, teacher_dim),
    ).to(device)
    opt = torch.optim.AdamW(proj.parameters(), lr=1e-3, weight_decay=1e-4)

    n_epochs = 30
    batch_size = 256
    for epoch in range(n_epochs):
        proj.train()
        perm_e = torch.randperm(len(X_train))
        losses = []
        for i in range(0, len(X_train), batch_size):
            b = perm_e[i : i + batch_size]
            x = X_train[b]
            y = Y_train[b]
            pred = proj(x)
            pred_n = F.normalize(pred, dim=1)
            y_n = F.normalize(y, dim=1)
            loss = (1 - (pred_n * y_n).sum(-1)).mean()
            opt.zero_grad()
            loss.backward()
            opt.step()
            losses.append(loss.item())
        train_loss = float(np.mean(losses))

        proj.eval()
        with torch.no_grad():
            pv = proj(X_val)
            pv_n = F.normalize(pv, dim=1)
            yv_n = F.normalize(Y_val, dim=1)
            val_loss = float((1 - (pv_n * yv_n).sum(-1)).mean().item())

        # Compute OOO acc using projected DINOv2 features (all concepts)
        with torch.no_grad():
            all_proj = proj(torch.from_numpy(dino_mat).float().to(device)).cpu().numpy()
        cur_acc, _ = ooo_accuracy(all_proj, triplets_v, ooo_pos_v)

        experiment_data["THINGS"]["losses"]["train"].append(train_loss)
        experiment_data["THINGS"]["losses"]["val"].append(val_loss)
        experiment_data["THINGS"]["metrics"]["train"].append(train_loss)
        experiment_data["THINGS"]["metrics"]["val"].append(cur_acc)

        print(
            f"Epoch {epoch+1}/{n_epochs}: train_loss={train_loss:.4f}, validation_loss={val_loss:.4f}, OOO_acc={cur_acc:.4f}"
        )

    # Final aligned accuracy
    proj.eval()
    with torch.no_grad():
        all_proj = proj(torch.from_numpy(dino_mat).float().to(device)).cpu().numpy()
    aligned_acc, aligned_pred = ooo_accuracy(all_proj, triplets_v, ooo_pos_v)
    print(f"\n=== Aligned DINOv2 OOO accuracy: {aligned_acc:.4f} ===")
    print(
        f"   Baseline: {baseline_acc:.4f} | Teacher: {teacher_acc:.4f} | Aligned: {aligned_acc:.4f}"
    )
    experiment_data["THINGS"]["aligned_ooo_acc"] = float(aligned_acc)
